package org.springframework.samples.petclinic.util;

import java.util.Map;

/**
 * Fixed lookup from an owner's region (its "locality", see {@link OwnerRegion}) to its
 * IANA timezone name. The table is pinned; a region with no entry — including
 * {@link CityRegion#UNKNOWN} — has no known timezone and returns {@code null}.
 */
public final class RegionTimezone {

    /** Region to its IANA timezone name. */
    private static final Map<String, String> REGION_TIMEZONE = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    private RegionTimezone() {
    }

    /**
     * The IANA timezone name for the given region, or {@code null} when the region has no
     * entry in the pinned table.
     *
     * @param region the owner's region (its locality)
     * @return the IANA timezone name, or {@code null} when none applies
     */
    public static String of(String region) {
        return REGION_TIMEZONE.get(region);
    }
}
=== util/CityRegion.java ===
package org.springframework.samples.petclinic.util;

import java.util.Locale;
import java.util.Map;

/**
 * Fixed lookup from an owner's city to its canonical region (its "locality"). The table
 * is pinned; any city not listed has locality {@link #UNKNOWN}.
 */
public final class CityRegion {

    /** The locality returned for any city not present in {@link #CITY_REGION}. */
    public static final String UNKNOWN = "UNKNOWN";

    /** City (matched case-insensitively) to canonical region string. */
    private static final Map<String, String> CITY_REGION = Map.of(
        "sydney", "NSW",
        "melbourne", "VIC",
        "brisbane", "QLD");

    private CityRegion() {
    }

    /**
     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
     * in the table. Matching is case-insensitive; a null city is {@link #UNKNOWN}.
     */
    public static String localityOf(String city) {
        if (city == null) {
            return UNKNOWN;
        }
        return CITY_REGION.getOrDefault(city.toLowerCase(Locale.ROOT), UNKNOWN);
    }
}
=== util/PostcodeRange.java ===
package org.springframework.samples.petclinic.util;

import java.util.Map;

/**
 * Fixed inclusive 4-digit postcode ranges keyed by an owner's region (as derived by
 * {@link CityRegion}). The table is pinned; a region with no entry — including
 * {@link CityRegion#UNKNOWN} — accepts any well-formed 4-digit postcode.
 */
public final class PostcodeRange {

    /** Region to its inclusive {@code {low, high}} 4-digit postcode range. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    private PostcodeRange() {
    }

    /**
     * Whether the given 4-digit {@code postcode} is valid for {@code city}. A city whose
     * region has no known range (the permissive default) accepts any postcode.
     *
     * @param city     the owner's city, mapped to a region via {@link CityRegion}
     * @param postcode a well-formed 4-digit postcode string
     * @return {@code true} when the postcode falls in the city's region range, or the
     *         region has no known range
     */
    public static boolean isValidForCity(String city, String postcode) {
        int[] range = REGION_RANGE.get(CityRegion.localityOf(city));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }

    /**
     * The region whose range contains the given postcode, or {@code null} when the
     * postcode is absent, not a well-formed 4-digit value, or in no known range.
     *
     * @param postcode a postcode string; may be null
     * @return the matching region, or {@code null} when none applies
     */
    public static String regionOf(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}

